    public enum FontRole: Sendable {
        case display
        case body

        /// The bundled variable font's PostScript name (registered in Info.plist's UIAppFonts).
        public var postScriptName: String {
            switch self {
            case .display: return "BricolageGrotesque-96ptExtraBold"
            case .body: return "Figtree-Light"
            }
        }
    }

